import React, { useState, useCallback, useMemo } from 'react';
import { 
  Paper, Typography, IconButton, List, ListItem, ListItemText, 
  CircularProgress, Alert, Box
} from '@mui/material';
import { useUserData } from './UserContext';
import apiCall from './api';
import { useCachedResource, FreshnessNote } from './widgetCache';
import { loadHomeSection } from './homeData';

const toHistory = (response) => {
  if (response && response.success && Array.isArray(response.history)) {
    return response.history;
  }
  throw new Error("Unexpected response format");
};

const HistoryComponent = () => {
  const { userData } = useUserData();
  const [currentDate, setCurrentDate] = useState(new Date());
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth() + 1;
  const today = new Date();
  const isCurrentMonth = year === today.getFullYear() && month === today.getMonth() + 1;

  // One month per request (the backend used to send the whole history every
  // time). The current month comes with the batched home request on first
  // load; other months are fetched - and cached - when you go to them.
  const loadHistory = useCallback(async ({ firstLoad } = {}) => {
    const single = async () => toHistory(await apiCall('dashboard_script', 'getWorkHistory', {
      username: userData.username,
      googleToken: userData.googleToken,
      year,
      month,
    }));
    if (!isCurrentMonth) return single();
    return loadHomeSection('workHistory', userData,
      single, { firstLoad }).then((d) => (Array.isArray(d) ? d : toHistory(d)));
  }, [userData, year, month, isCurrentMonth]);

  const { data, savedAt, loading: refreshing, error: fetchError } =
    useCachedResource(`workHistory:${year}-${month}`, loadHistory);
  const allHistory = useMemo(() => data || [], [data]);
  // Spinner and error box only when there's nothing (cached) to show yet.
  const loading = refreshing && data === undefined;
  const error = fetchError && data === undefined
    ? "An error occurred while fetching history: " + fetchError.message
    : null;

  const handleMonthChange = (direction) => {
    setCurrentDate(prevDate => {
      const newDate = new Date(prevDate);
      newDate.setMonth(prevDate.getMonth() + direction);
      return newDate;
    });
  };

  const filteredHistory = useMemo(() => {
    return allHistory.filter(entry => 
      parseInt(entry.month) === currentDate.getMonth() + 1 &&
      parseInt(entry.year) === currentDate.getFullYear()
    ).sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
  }, [allHistory, currentDate]);

  return (
    <Paper elevation={3} sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
        <IconButton onClick={() => handleMonthChange(-1)} aria-label="Previous month">
          &lt;
        </IconButton>
        <Typography variant="h6" sx={{ flexGrow: 1, textAlign: 'center' }}>
          {currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
        </Typography>
        <IconButton onClick={() => handleMonthChange(1)} aria-label="Next month">
          &gt;
        </IconButton>
      </Box>
      <FreshnessNote savedAt={savedAt} loading={refreshing} error={fetchError} sx={{ textAlign: 'center', mt: -1.5, mb: 1 }} />

      {loading && <CircularProgress sx={{ alignSelf: 'center', my: 2 }} />}
      
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}
      
      {!loading && !error && (
        <List sx={{ flexGrow: 1, overflowY: 'auto', maxHeight: 400 }}>
          {filteredHistory.length > 0 ? (
            filteredHistory.map((entry, index) => (
              <ListItem key={index} divider>
                <ListItemText
                  primary={`${entry.year}-${entry.month}-${entry.day}`}
                  secondary={`Work Done: ${entry.workDone || 'N/A'}, Amount: ${entry.amount || 'N/A'}€`}
                />
              </ListItem>
            ))
          ) : (
            <ListItem>
              <ListItemText primary="No work history found for this month." />
            </ListItem>
          )}
        </List>
      )}
    </Paper>
  );
};

export default HistoryComponent;