import React from 'react';
import {
  Drawer, Box, ListItemButton, ListItemIcon, ListItemText,
  Typography, IconButton, Divider, Tooltip, useMediaQuery, useTheme,
} from '@mui/material';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import CloseIcon from '@mui/icons-material/Close';
import yurankaLogo from '../assets/brand/yuranka-logo.webp';

const EXPANDED_WIDTH = 250;
const COLLAPSED_WIDTH = 76;

const Sidebar = ({ sections, activeKey, onSelect, collapsed, onToggleCollapse, mobileOpen, onCloseMobile }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const isCollapsed = collapsed && !isMobile;
  const width = isCollapsed ? COLLAPSED_WIDTH : EXPANDED_WIDTH;

  const content = (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', overflowX: 'hidden' }}>
      <Box sx={{
        display: 'flex', alignItems: 'center', gap: 1.25,
        // 20px + half the 36px logo = 38px = half the collapsed width, so the
        // logo sits on the same x in both states and never slides.
        px: 2.5,
        // Same height as the TopBar toolbar so the two bottom borders line up
        // into one continuous rule across the sidebar and header.
        minHeight: { xs: 56, sm: 64 },
        justifyContent: 'flex-start',
      }}>
        <Box
          component="img"
          src={yurankaLogo}
          alt=""
          sx={{ width: 36, height: 36, objectFit: 'contain', flexShrink: 0, display: 'block' }}
        />
        {(
          <Box sx={{ minWidth: 0, opacity: isCollapsed ? 0 : 1, transition: 'opacity .15s ease', pointerEvents: 'none' }}>
            <Typography
              variant="subtitle1"
              sx={{ fontWeight: 700, lineHeight: 1.1, whiteSpace: 'nowrap', letterSpacing: '-0.01em' }}
            >
              Yuranka
            </Typography>
            <Typography
              variant="caption"
              sx={{
                display: 'block', color: 'text.secondary', whiteSpace: 'nowrap',
                fontWeight: 700, fontSize: '0.6rem', letterSpacing: '0.14em', textTransform: 'uppercase',
              }}
            >
              Staff
            </Typography>
          </Box>
        )}
        {isMobile && (
          <IconButton onClick={onCloseMobile} sx={{ ml: 'auto' }} aria-label="Close menu">
            <CloseIcon fontSize="small" />
          </IconButton>
        )}
      </Box>
      <Divider />
      <Box component="nav" aria-label="Main navigation" sx={{ flex: 1, overflowY: 'auto', overflowX: 'hidden', px: 1, py: 1.5 }}>
        {sections.map((section) => (
          <Box key={section.title} sx={{ mb: 1.5 }}>
            {/* Fixed-height slot, always rendered: collapsing swaps the title for
                a short rule instead of removing it, so the items below never
                shift vertically when the sidebar toggles. */}
            <Box sx={{ height: 28, display: 'flex', alignItems: 'center', justifyContent: isCollapsed ? 'center' : 'flex-start', px: 1.25 }}>
              {isCollapsed ? (
                <Box sx={{ width: 20, height: '1px', bgcolor: 'divider' }} />
              ) : (
                <Typography
                  variant="overline"
                  noWrap
                  sx={{ lineHeight: 1, color: 'text.secondary', fontWeight: 700, letterSpacing: '.06em' }}
                >
                  {section.title}
                </Typography>
              )}
            </Box>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25 }}>
              {section.items.map((item) => {
                const isActive = item.key === activeKey;
                const Icon = item.icon;
                const buttonEl = (
                  <ListItemButton
                    selected={isActive}
                    onClick={() => onSelect(item.key)}
                    sx={{
                      position: 'relative',
                      borderRadius: 2,
                      // Layout is identical collapsed/expanded: icon centre is
                      // 8 + 12 + 18 = 38px in both, labels just fade and get
                      // clipped by the narrower drawer. Nothing re-flows.
                      justifyContent: 'flex-start',
                      px: 1.5,
                      transition: 'background-color .15s ease, color .15s ease',
                      '&.Mui-selected': {
                        bgcolor: 'action.selected',
                        color: 'primary.main',
                        '& .MuiListItemIcon-root': { color: 'primary.main' },
                        '&:hover': { bgcolor: 'action.selected' },
                        ...(isCollapsed ? {} : {
                          '&::before': {
                            content: '""',
                            position: 'absolute',
                            left: -8,
                            top: '22%',
                            bottom: '22%',
                            width: 3,
                            borderRadius: 4,
                            bgcolor: 'primary.main',
                          },
                        }),
                      },
                    }}
                  >
                    <ListItemIcon sx={{ minWidth: 36, justifyContent: 'center', color: 'inherit' }}>
                      <Icon fontSize="small" />
                    </ListItemIcon>
                    <ListItemText
                      primaryTypographyProps={{ fontSize: '.87rem', fontWeight: isActive ? 700 : 500, noWrap: true }}
                      sx={{ opacity: isCollapsed ? 0 : 1, transition: 'opacity .15s ease' }}
                    >
                      {item.label}
                    </ListItemText>
                  </ListItemButton>
                );
                return (
                  <Box key={item.key}>
                    <Tooltip title={item.label} placement="right" disableHoverListener={!isCollapsed} disableFocusListener={!isCollapsed} disableTouchListener={!isCollapsed}>
                      {buttonEl}
                    </Tooltip>
                  </Box>
                );
              })}
            </Box>
          </Box>
        ))}
      </Box>
    </Box>
  );

  if (isMobile) {
    return (
      <Drawer
        variant="temporary"
        open={mobileOpen}
        onClose={onCloseMobile}
        ModalProps={{ keepMounted: true }}
        sx={{ '& .MuiDrawer-paper': { width: EXPANDED_WIDTH, boxSizing: 'border-box', borderRadius: 0 } }}
      >
        {content}
      </Drawer>
    );
  }

  return (
    <>
      <Drawer
        variant="permanent"
        sx={{
          width,
          flexShrink: 0,
          transition: 'width .2s ease',
          '& .MuiDrawer-paper': {
            width, boxSizing: 'border-box', overflowX: 'hidden', transition: 'width .2s ease', borderRadius: 0,
            boxShadow: (t) => `6px 0 28px -16px ${t.palette.mode === 'dark' ? 'rgba(239,68,68,0.45)' : 'rgba(220,38,38,0.25)'}`,
          },
        }}
      >
        {content}
      </Drawer>

      {/* Collapse toggle: sits on the sidebar's right border, level with the
          logo. It's a sibling of the Drawer (not inside it) because the drawer
          paper clips overflow, and it tracks the drawer width with the same
          transition so it glides rather than snaps. */}
      <IconButton
        onClick={onToggleCollapse}
        aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
        size="small"
        sx={{
          position: 'fixed',
          top: 18,
          left: width - 14,
          width: 28,
          height: 28,
          zIndex: (t) => t.zIndex.drawer + 1,
          bgcolor: 'background.paper',
          color: 'text.secondary',
          border: '1px solid',
          borderColor: 'divider',
          transition: 'left .2s ease, color .15s ease, border-color .15s ease, transform .12s ease',
          '&:hover': { bgcolor: 'background.paper', color: 'primary.main', borderColor: 'primary.main' },
        }}
      >
        {collapsed ? <ChevronRightIcon sx={{ fontSize: 18 }} /> : <ChevronLeftIcon sx={{ fontSize: 18 }} />}
      </IconButton>
    </>
  );
};

export default Sidebar;
