import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { Box, CircularProgress } from '@mui/material';
import { getDevAuth, devLogin } from './devAuth';

const UserContext = createContext();

// The signed-in session survives a page refresh: it's kept in sessionStorage
// (this tab only - closing the tab still signs you out). Without it every
// refresh meant a fresh 4-6s login, and each login rotates the token, which
// signs the same account out on every other device.
const SESSION_KEY = 'yuranka-session';

const readSession = () => {
  try {
    const raw = sessionStorage.getItem(SESSION_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) {
    return null;
  }
};

const writeSession = (data) => {
  try {
    if (data) sessionStorage.setItem(SESSION_KEY, JSON.stringify(data));
    else sessionStorage.removeItem(SESSION_KEY);
  } catch (e) {
    // Storage blocked - the app still works, a refresh just needs a new login.
  }
};

export const UserProvider = ({ children }) => {
  // Normal case: the saved session if there is one, else null so the login
  // screen shows. With the dev-only auth=off switch (see devAuth.js) it starts
  // as a fake user, or as null while a real auto-login is in flight - unless a
  // saved session can be reused, which skips the auto-login entirely.
  const devAuth = getDevAuth();
  const [userData, setUserDataState] = useState(() =>
    devAuth.mode === 'fake' ? devAuth.user : readSession()
  );
  const [devLoginPending, setDevLoginPending] = useState(
    () => devAuth.mode === 'login' && !readSession()
  );

  const setUserData = useCallback((data) => {
    writeSession(data);
    setUserDataState(data);
  }, []);

  // Check-in status changes after login (CheckInContext); keep the saved copy
  // current so a refresh shows the right status and buttons. Only the stored
  // copy is touched - updating userData itself would re-fetch every widget.
  const rememberStatus = useCallback((status) => {
    const saved = readSession();
    if (!saved) return;
    writeSession({
      ...saved,
      status,
      additionalData: { ...(saved.additionalData || {}), status },
    });
  }, []);

  const [avatarSettings, setAvatarSettings] = useState({
    gender: 'male',
    skinTone: '#FFD5B4',
    outfitColor: '#2196F3',
    hairStyle: 'short',
    accessories: [],
    facialExpression: 'smile'
  });

  useEffect(() => {
    if (!devLoginPending) return undefined;
    let active = true;
    devLogin(devAuth.credentials)
      .then((user) => { if (active) setUserData(user); })
      .catch((error) => {
        // Fall through to the normal login screen so you can still sign in by hand.
        console.error('[dev] Auto-login failed, showing the login screen:', error);
      })
      .finally(() => { if (active) setDevLoginPending(false); });
    return () => { active = false; };
    // Only ever runs on mount: devLoginPending starts true at most once.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Load avatar settings from localStorage on initial render
  useEffect(() => {
    const saved = localStorage.getItem('avatarSettings');
    if (saved) {
      try {
        setAvatarSettings(JSON.parse(saved));
      } catch (error) {
        console.error('Error parsing saved avatar settings:', error);
      }
    }
  }, []);

  // Save avatar settings to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('avatarSettings', JSON.stringify(avatarSettings));
  }, [avatarSettings]);

  return (
    <UserContext.Provider value={{ 
      userData,
      setUserData,
      rememberStatus,
      isAuthenticated: !!userData,
      avatarSettings, 
      setAvatarSettings 
    }}>
      {devLoginPending ? (
        // Don't flash the login form while the dev auto-login completes.
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh' }}>
          <CircularProgress aria-label="Signing in" />
        </Box>
      ) : children}
    </UserContext.Provider>
  );
};

export const useUserData = () => {
  const context = useContext(UserContext);
  if (context === undefined) {
    throw new Error('useUserData must be used within a UserProvider');
  }
  return context;
};