import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { useUserData } from './UserContext';

const CheckInContext = createContext();

export const useCheckIn = () => {
  const context = useContext(CheckInContext);
  if (!context) {
    throw new Error('useCheckIn must be used within a CheckInProvider');
  }
  return context;
};

export const CheckInProvider = ({ children }) => {
    const { userData, rememberStatus } = useUserData();
    const [status, setStatus] = useState(userData?.status || 'default');

    useEffect(() => {
      if (userData?.status) {
        setStatus(userData.status);
      }
    }, [userData]);

    const updateStatus = useCallback((newStatus) => {
      setStatus(newStatus);
      // So a page refresh (which restores the saved session) shows this
      // status, not the one from when the user signed in.
      rememberStatus(newStatus);
    }, [rememberStatus]);
  
    return (
      <CheckInContext.Provider value={{ status, updateStatus }}>
        {children}
      </CheckInContext.Provider>
    );
  };