import React, { useCallback } from 'react';
import {
  Typography, CircularProgress, Alert,
  Card, CardContent, List, ListItem, ListItemText,
  Box
} from '@mui/material';
import apiCall from './api';
import { useUserData } from './UserContext';
import { useCachedResource, FreshnessNote } from './widgetCache';
import { loadHomeSection } from './homeData';

const NoticeBoardDisplay = () => {
  const { userData } = useUserData();

  const loadMessages = useCallback(async ({ firstLoad } = {}) => {
    const response = await loadHomeSection('noticeBoard', userData, () => apiCall('dashboard_script', 'getNoticeBoardMessages', {
      role: userData.role,
      googleToken: userData.googleToken,
      username: userData.username
    }), { firstLoad });
    if (response && Array.isArray(response)) return response;
    throw new Error('Failed to fetch noticeboard messages');
  }, [userData]);

  const { data, savedAt, loading: refreshing, error: fetchError } = useCachedResource('noticeBoard', loadMessages);
  const messages = data || [];
  const loading = refreshing && data === undefined;
  const error = fetchError && data === undefined
    ? 'Failed to load noticeboard messages. Please try again.'
    : null;

  if (loading) {
    return (
      <Card>
        <CardContent style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 100 }}>
          <CircularProgress />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card sx={{ height: '400px', display: 'flex', flexDirection: 'column' }}>
      <CardContent sx={{ flexGrow: 0 }}>
        <Typography variant="h6" gutterBottom>
          Noticeboard
        </Typography>
        <FreshnessNote savedAt={savedAt} loading={refreshing} error={fetchError} sx={{ mt: -1, mb: 1 }} />
        {error && (
          <Alert severity="error" sx={{ marginBottom: 2 }}>
            {error}
          </Alert>
        )}
      </CardContent>
      <Box sx={{ flexGrow: 1, overflow: 'auto', px: 2 }}>
        <List sx={{ width: '100%' }}>
          {messages.map((message, index) => (
            <ListItem
              key={index}
              divider
              sx={{
                flexDirection: 'column',
                alignItems: 'flex-start',
                py: 2
              }}
            >
              <ListItemText
                primary={message.title}
                secondary={
                  <>
                    <Typography component="span" variant="body2" color="textPrimary">
                      {message.content}
                    </Typography>
                    <br />
                    <Typography component="span" variant="caption" color="textSecondary">
                      Posted on: {new Date(message.date).toLocaleString()}
                    </Typography>
                  </>
                }
              />
            </ListItem>
          ))}
        </List>
      </Box>
    </Card>
  );
};

export default NoticeBoardDisplay;