import React, { useState, useCallback } from 'react';
import {
  Typography, Container, TextField, Button, Box, Tabs, Tab,
  Alert, CircularProgress
} from '@mui/material';
import apiCall from './api';
import { useUserData } from './UserContext';
import { useCheckIn } from './CheckInContext';
import yurankaLogo from './assets/brand/yuranka-logo.webp';
import storePhoto from './assets/brand/store.webp';

const AuthComponent = ({ onAuthenticated }) => {
  const { setUserData } = useUserData();
  const { updateStatus } = useCheckIn();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [authData, setAuthData] = useState({ username: '', password: '', email: '' });
  const [authTab, setAuthTab] = useState(0);

  const handleAuth = useCallback(async (action) => {
    setLoading(true);
    setError(null);
    try {
      const scriptId = 'dashboard_script';
      const response = await apiCall(scriptId, action, authData);

      if (!response.success) {
        throw new Error(response.message || 'Authentication failed');
      }

      if (action === 'login') {
        const newUserData = {
          username: response.username,
          role: response.role,
          googleToken: response.token,
          status: response.additionalData.status,
          additionalData: response.additionalData,
          jobDescription: response.jobDescription, // Add this line
          email:response.email,
        };
        setUserData(newUserData);
        updateStatus(newUserData.status);
        onAuthenticated(true);
      }

      return true;
    } catch (err) {
      console.error(`${action} error:`, err);
      setError(err.message || `An unexpected error occurred during ${action}.`);
      return false;
    } finally {
      setLoading(false);
    }
  }, [authData, setUserData, updateStatus, onAuthenticated]);

  const handleAuthSubmit = useCallback(async (e) => {
    e.preventDefault();
    const success = await handleAuth(authTab === 0 ? 'login' : 'create-account');
    if (!success) {
      setAuthData(prev => ({ ...prev, password: '' }));
    }
  }, [handleAuth, authTab]);

  const handleInputChange = useCallback((e) => {
    const { name, value } = e.target;
    setAuthData(prev => ({ ...prev, [name]: value }));
  }, []);

  return (
    <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'background.default' }}>
      {/* Brand panel - a real photo of the shop floor under a dark scrim, so
          it stays the same "walking into Yuranka" moment regardless of the
          app's light/dark toggle. Hidden below md; the form works standalone. */}
      <Box sx={{
        display: { xs: 'none', md: 'flex' },
        flexDirection: 'column',
        justifyContent: 'space-between',
        width: '44%',
        minWidth: 400,
        maxWidth: 600,
        p: 6,
        position: 'relative',
        overflow: 'hidden',
        color: '#FAFAFA',
        bgcolor: '#0A0A0A',
        backgroundImage: `linear-gradient(180deg, rgba(10,10,10,0.72) 0%, rgba(10,10,10,0.88) 55%, #0A0A0A 100%), url(${storePhoto})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
      }}>
        {/* brand-red edge, echoing the storefront's accent */}
        <Box sx={{ position: 'absolute', inset: 0, borderRight: '3px solid', borderColor: '#EF4444', pointerEvents: 'none' }} />

        <Box
          component="img"
          src={yurankaLogo}
          alt="Yuranka Games"
          sx={{ width: 190, maxWidth: '60%', display: 'block', position: 'relative' }}
        />

        <Box sx={{ position: 'relative' }}>
          <Typography sx={{
            fontWeight: 700, fontSize: '2.35rem', lineHeight: 1.1,
            letterSpacing: '-0.03em', mb: 2, maxWidth: 420,
          }}>
            Back for another round.
          </Typography>
          <Typography sx={{ color: 'rgba(250,250,250,0.7)', fontSize: '.98rem', maxWidth: 380 }}>
            Shifts, stock, events and the loyalty counter — everything it takes
            to run the shop floor, in one place.
          </Typography>
        </Box>

        <Typography sx={{
          position: 'relative', color: 'rgba(250,250,250,0.45)', fontSize: '.72rem',
          fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase',
        }}>
          Magic · Pokémon · Yu-Gi-Oh! · One Piece · Flesh and Blood
        </Typography>
      </Box>

      {/* Form panel - respects the app's current light/dark theme */}
      <Box sx={{
        flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', p: 3,
        position: 'relative',
        // faint brand-red bloom so the form doesn't float in a flat void
        backgroundImage: (t) => `radial-gradient(60% 50% at 50% 42%, ${
          t.palette.mode === 'dark' ? 'rgba(239,68,68,0.10)' : 'rgba(220,38,38,0.06)'
        } 0%, transparent 70%)`,
      }}>
        <Container component="main" maxWidth="xs" disableGutters>
          <Box sx={{
            display: { xs: 'flex', md: 'none' },
            flexDirection: 'column', alignItems: 'center', gap: 1, mb: 3,
          }}>
            <Box component="img" src={yurankaLogo} alt="Yuranka Games" sx={{ width: 150, display: 'block' }} />
          </Box>

          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'stretch',
              bgcolor: 'background.paper',
              p: 4,
              borderRadius: 3,
              border: '1px solid',
              borderColor: 'divider',
            }}
          >
            <Typography
              variant="overline"
              sx={{ color: 'primary.main', fontWeight: 700, lineHeight: 1, mb: 1 }}
            >
              Staff Access
            </Typography>
            <Typography component="h1" variant="h5" gutterBottom>
              {authTab === 0 ? "Sign in" : "Create account"}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              {authTab === 0
                ? 'Sign in with your staff account to start your shift.'
                : 'Set up a staff account to get started.'}
            </Typography>
            <Tabs value={authTab} onChange={(e, newValue) => setAuthTab(newValue)} sx={{ mb: 2 }}>
              <Tab label="Sign In" />
              <Tab label="Create Account" />
            </Tabs>
            {error && <Alert severity="error" sx={{ mb: 2, width: '100%' }}>{error}</Alert>}
            <Box component="form" onSubmit={handleAuthSubmit} noValidate sx={{ mt: 1, width: '100%' }}>
              <TextField
                margin="normal"
                required
                fullWidth
                id="username"
                label="Username"
                name="username"
                autoComplete="username"
                autoFocus
                value={authData.username}
                onChange={handleInputChange}
              />
              <TextField
                margin="normal"
                required
                fullWidth
                name="password"
                label="Password"
                type="password"
                id="password"
                autoComplete="current-password"
                value={authData.password}
                onChange={handleInputChange}
              />
              {authTab === 1 && (
                <TextField
                  margin="normal"
                  required
                  fullWidth
                  name="email"
                  label="Email Address"
                  type="email"
                  id="email"
                  autoComplete="email"
                  value={authData.email}
                  onChange={handleInputChange}
                />
              )}
              <Button
                type="submit"
                fullWidth
                variant="contained"
                color="primary"
                sx={{ mt: 3, mb: 2, py: 1.2 }}
                disabled={loading}
              >
                {loading ? <CircularProgress size={24} /> : (authTab === 0 ? "Sign In" : "Create Account")}
              </Button>
            </Box>
          </Box>
        </Container>
      </Box>
    </Box>
  );
};

export default AuthComponent;
