import React, { useCallback } from 'react';
import {
  Paper, Typography, Box, List, ListItem, ListItemText,
  CircularProgress, Divider, Chip, Button, Alert
} from '@mui/material';
import RefreshIcon from '@mui/icons-material/Refresh';
import { useUserData } from './UserContext';
import apiCall from './api';
import { formatTime, formatBreakTime } from './timeFormat';
import { useCachedResource, FreshnessNote } from './widgetCache';
import { loadHomeSection } from './homeData';

const WorkerActivityDisplay = () => {
  const { userData } = useUserData();

  const loadWorkerActivity = useCallback(async ({ firstLoad } = {}) => {
    const response = await loadHomeSection('workerActivity', userData, () => apiCall('dashboard_script', 'getWorkerActivity', {
      googleToken: userData.googleToken,
      username: userData.username
    }), { firstLoad });
    if (Array.isArray(response)) return response;
    throw new Error('Unexpected response format');
  }, [userData]);

  // A failed refresh used to leave the previous list on screen with no hint
  // it was old. Now the list stays but FreshnessNote says the refresh failed
  // and how old the data is.
  const {
    data, savedAt, loading: refreshing, error, refresh: fetchWorkerActivity,
  } = useCachedResource('workerActivity', loadWorkerActivity);
  const workerData = data || [];
  const loading = refreshing && data === undefined;

  const getStatusColor = (status) => {
    switch (status) {
      case 'Checked In':
        return 'success';
      case 'Checked Out':
        return 'error';
      case 'Going on Break':
        return 'warning';
      case 'Returning from Break':
        return 'info';
      default:
        return 'default';
    }
  };

  if (loading) {
    return <CircularProgress color="primary" />;
  }

  return (
    <Paper elevation={3} sx={{
      height: '100%',
      display: 'flex',
      flexDirection: 'column',
      maxHeight: '800px',
      overflow: 'hidden',
    }}>
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', p: 2 }}>
        <Box>
          <Typography variant="h6">Worker Activity</Typography>
          <FreshnessNote savedAt={savedAt} loading={refreshing} error={error} />
        </Box>
        <Button
          variant="outlined"
          size="small"
          startIcon={<RefreshIcon />}
          onClick={fetchWorkerActivity}
          disabled={refreshing}
          color="primary"
        >
          Refresh
        </Button>
      </Box>
      {error && data === undefined && (
        <Alert severity="error" sx={{ mx: 2, mb: 1 }}>
          Couldn't load worker activity: {error.message}
        </Alert>
      )}
      <Box sx={{ flexGrow: 1, overflow: 'auto', overflowX: 'hidden' }}>
        <List>
          {workerData.map((worker, index) => (
            <React.Fragment key={index}>
              <ListItem
                alignItems="flex-start"
                sx={{
                  '&:hover': {
                    backgroundColor: 'action.hover',
                  },
                }}
              >
                <ListItemText
                  primary={
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                      <Typography>{worker.name}</Typography>
                      <Chip
                        label={worker.status}
                        size="small"
                        color={getStatusColor(worker.status)}
                      />
                    </Box>
                  }
                  secondary={
                    <Box sx={{ mt: 1, display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                      <Typography component="span" variant="body2" color="text.secondary">
                        Hours Today: {Number(worker.hoursToday || 0).toFixed(2)}h
                        <span style={{ marginLeft: 12 }}>Breaks: {worker.totalBreaksToday || 0}</span>
                        <span style={{ marginLeft: 12 }}>Break Time: {formatBreakTime(worker.totalBreakMinutesToday)}</span>
                      </Typography>
                      {(worker.breaks || []).length > 0 && (
                        <Box component="span" sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                          {(worker.breaks || []).map((b, i) => (
                            <Typography key={i} component="span" variant="body2" color="text.disabled">
                              {formatTime(b.start)} → {b.ongoing ? 'Ongoing' : formatTime(b.end)}
                            </Typography>
                          ))}
                        </Box>
                      )}
                    </Box>
                  }
                />
              </ListItem>
              {index < workerData.length - 1 && <Divider variant="inset" component="li" />}
            </React.Fragment>
          ))}
        </List>
      </Box>
    </Paper>
  );
};

export default WorkerActivityDisplay;