import { lazy } from 'react';

// React.lazy plus a .preload() that starts downloading the code early.
// The bundler caches the import, so a preloaded component renders instantly
// when it's finally opened (React.lazy reuses the same request).
const lazyWithPreload = (factory) => {
  const Component = lazy(factory);
  Component.preload = factory;
  return Component;
};

// Download the given lazy components once the browser has nothing better to
// do, so they're ready before anyone clicks. Errors are ignored here - if a
// download fails, the normal load on open will try again and show it.
export const preloadWhenIdle = (components) => {
  const run = () => {
    components.forEach((Component) => {
      if (Component && typeof Component.preload === 'function') {
        Component.preload().catch(() => {});
      }
    });
  };
  if (typeof window !== 'undefined' && 'requestIdleCallback' in window) {
    const handle = window.requestIdleCallback(run, { timeout: 5000 });
    return () => window.cancelIdleCallback(handle);
  }
  const timer = setTimeout(run, 2000);
  return () => clearTimeout(timer);
};

export default lazyWithPreload;
