import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Typography } from '@mui/material';
import { useUserData } from './UserContext';

// Home-widget data cached per browser tab (sessionStorage), so coming back to
// the dashboard shows the last result instantly while a fresh copy loads in
// the background. Keyed by username so two people on one machine never see
// each other's data, and wiped on sign-out (clearWidgetCache).
const PREFIX = 'yuranka-widget:';

const keyFor = (username, name) => `${PREFIX}${username}:${name}`;

const readWidgetCache = (username, name) => {
  if (!username) return null;
  try {
    const raw = sessionStorage.getItem(keyFor(username, name));
    return raw ? JSON.parse(raw) : null;
  } catch (e) {
    return null;
  }
};

const writeWidgetCache = (username, name, data) => {
  const entry = { data, savedAt: Date.now() };
  if (!username) return entry;
  try {
    sessionStorage.setItem(keyFor(username, name), JSON.stringify(entry));
  } catch (e) {
    // Storage full or blocked - the widget still works, just without the cache.
  }
  return entry;
};

export const clearWidgetCache = () => {
  try {
    Object.keys(sessionStorage)
      .filter((key) => key.startsWith(PREFIX))
      .forEach((key) => sessionStorage.removeItem(key));
  } catch (e) {
    // Nothing cached, nothing to clear.
  }
};

// Loads data for a home widget: returns the cached copy straight away (if
// there is one) and refreshes it in the background.
//
//   load     async () => data. Throw to signal failure. Keep it stable
//            (useCallback) - it re-runs whenever it changes. It receives
//            { firstLoad: true } for the automatic load (so it can use the
//            batched home request) and {} for a manual refresh.
//   name     cache key; may change (e.g. "workHistory:2026-10" when the
//            month changes) - each key keeps its own cached copy.
//   options  { cache: false } to skip storage (e.g. for secrets) and only
//            get the refresh/error handling.
export const useCachedResource = (name, load, { cache = true } = {}) => {
  const { userData } = useUserData();
  const username = userData?.username;
  // Fetched results by cache key, so switching key (month) never shows the
  // previous key's data while the new one loads.
  const [entries, setEntries] = useState({});
  const entry = entries[name] !== undefined
    ? entries[name]
    : (cache ? readWidgetCache(username, name) : null);
  // true from the start: the effect below fetches immediately, and widgets
  // shouldn't flash "nothing found" before the first request goes out.
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  // Ignore a slower, older request finishing after a newer one.
  const requestId = useRef(0);

  // Buttons call refresh(event) - only an explicit { firstLoad: true } counts.
  const refresh = useCallback(async (options) => {
    const firstLoad = Boolean(options && options.firstLoad === true);
    const id = ++requestId.current;
    setLoading(true);
    setError(null);
    try {
      const data = await load({ firstLoad });
      if (id !== requestId.current) return;
      const saved = cache ? writeWidgetCache(username, name, data) : { data, savedAt: Date.now() };
      setEntries((prev) => ({ ...prev, [name]: saved }));
    } catch (err) {
      if (id !== requestId.current) return;
      setError(err);
    } finally {
      if (id === requestId.current) setLoading(false);
    }
  }, [load, cache, username, name]);

  useEffect(() => {
    refresh({ firstLoad: true });
  }, [refresh]);

  return {
    data: entry ? entry.data : undefined,
    savedAt: entry ? entry.savedAt : null,
    loading,
    error,
    refresh,
  };
};

const formatAge = (savedAt, now) => {
  const minutes = Math.floor((now - savedAt) / 60000);
  if (minutes < 1) return 'just now';
  if (minutes < 60) return `${minutes} min ago`;
  const hours = Math.floor(minutes / 60);
  return `${hours} h ago`;
};

// One line under a widget's title: when the data was fetched, that it is
// refreshing, or - the important one - that the last refresh failed and what
// is on screen is old. Renders nothing until there is something to say.
export const FreshnessNote = ({ savedAt, loading, error, sx }) => {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(timer);
  }, []);

  if (!savedAt) return null;
  const age = formatAge(savedAt, now);

  if (error) {
    return (
      <Typography variant="caption" color="warning.main" sx={{ display: 'block', ...sx }}>
        Couldn't refresh - showing data from {age}
      </Typography>
    );
  }
  return (
    <Typography variant="caption" color="text.secondary" sx={{ display: 'block', ...sx }}>
      {loading ? 'Refreshing…' : `Updated ${age}`}
    </Typography>
  );
};

// Shared shape for widgets: a spinner only when there is nothing to show yet.
export const isFirstLoad = ({ data, loading }) => loading && data === undefined;

export default useCachedResource;
