import React, { useMemo } from 'react';
import { CssBaseline, ThemeProvider, createTheme, GlobalStyles } from '@mui/material';
import Dashboard from './Dashboard';
import { UserProvider } from './UserContext';
import { CheckInProvider } from './CheckInContext';
import { ThemeModeProvider, useThemeMode } from './ThemeModeContext';
import buildTheme from './theme';

const globalStyles = (theme) => ({
  '*': {
    scrollbarWidth: 'thin',
    scrollbarColor: `${theme.palette.mode === 'dark' ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.2)'} transparent`,
  },
  '*::-webkit-scrollbar': { width: 10, height: 10 },
  '*::-webkit-scrollbar-track': { background: 'transparent' },
  '*::-webkit-scrollbar-thumb': {
    backgroundColor: theme.palette.mode === 'dark' ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.2)',
    borderRadius: 8,
    border: '2px solid transparent',
    backgroundClip: 'padding-box',
  },
  '*::-webkit-scrollbar-thumb:hover': {
    backgroundColor: theme.palette.mode === 'dark' ? 'rgba(255,255,255,0.3)' : 'rgba(0,0,0,0.32)',
  },
  '::selection': {
    backgroundColor: theme.palette.mode === 'dark' ? 'rgba(239,68,68,0.35)' : 'rgba(220,38,38,0.22)',
  },
});

const AppShell = () => {
  const { mode } = useThemeMode();
  const theme = useMemo(() => createTheme(buildTheme(mode)), [mode]);

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <GlobalStyles styles={globalStyles} />
      <UserProvider>
        <CheckInProvider>
          <Dashboard />
        </CheckInProvider>
      </UserProvider>
    </ThemeProvider>
  );
};

const App = () => (
  <ThemeModeProvider>
    <AppShell />
  </ThemeModeProvider>
);

export default App;
