// Dev-only way to skip the login screen when running the worker locally.
//
// Turn it on with either:
//   http://localhost:3000/?auth=off        (per tab, no restart)
//   REACT_APP_AUTH=off                     (in .env.local, restart npm start)
//
// Auth stays ON (normal login screen) unless one of those is set.
//
// What happens once it is on:
//   - REACT_APP_DEV_USER + REACT_APP_DEV_PASS set  -> the real login call is
//     made for you in the background, so the token is genuine and every
//     backend returns real data. The login screen never shows.
//   - credentials missing                          -> a fake user is used
//     instead. Its token is fake, so only scripts routed to the local test
//     proxy (REACT_APP_LOCAL_SCRIPTS) will answer; fine for layout work.
//   - REACT_APP_DEV_ROLE=Store Manager             -> role for the fake user
//
// Nothing here ships: process.env.NODE_ENV is replaced with a constant at
// build time, so in a production build the early return below makes the rest
// of this file dead code and the credentials never reach the bundle.
import apiCall from './api';

let cached;

const compute = () => {
  if (process.env.NODE_ENV === 'production') return { mode: 'on' };

  const viaEnv = process.env.REACT_APP_AUTH === 'off';
  const viaUrl =
    typeof window !== 'undefined' &&
    new URLSearchParams(window.location.search).get('auth') === 'off';
  if (!viaEnv && !viaUrl) return { mode: 'on' };

  const username = process.env.REACT_APP_DEV_USER;
  const password = process.env.REACT_APP_DEV_PASS;
  if (username && password) {
    console.warn(`[dev] Auth is OFF - logging in automatically as "${username}".`);
    return { mode: 'login', credentials: { username, password } };
  }

  const role = process.env.REACT_APP_DEV_ROLE || 'Admin';
  console.warn(`[dev] Auth is OFF - using a fake "${role}" user. Its token is fake, so backends will reject it.`);
  return {
    mode: 'fake',
    user: {
      username: 'dev',
      role,
      googleToken: 'dev-token',
      status: 'Checked Out',
      additionalData: { status: 'Checked Out' },
      jobDescription: null,
      email: 'dev@localhost',
    },
  };
};

// 'on' | 'login' | 'fake' - computed once so every caller sees the same answer.
export const getDevAuth = () => {
  if (!cached) cached = compute();
  return cached;
};

// One login per page load, no matter how many times it is asked for. React
// StrictMode runs effects twice in dev, and every login rotates the token the
// backend stores, so two racing logins could leave the app holding a stale one.
let loginPromise;
export const devLogin = ({ username, password }) => {
  if (!loginPromise) {
    loginPromise = apiCall('dashboard_script', 'login', { username, password, email: '' }).then((response) => {
      if (!response || !response.success) {
        throw new Error((response && response.message) || 'Dev auto-login failed');
      }
      // Same shape AuthComponent builds after a manual login.
      return {
        username: response.username,
        role: response.role,
        googleToken: response.token,
        status: response.additionalData.status,
        additionalData: response.additionalData,
        jobDescription: response.jobDescription,
        email: response.email,
      };
    });
  }
  return loginPromise;
};
