// Palette lifted from the customer site (newyurankagames) so the worker tools
// and the storefront read as the same brand: Tailwind-neutral greys, a vivid
// brand red, Space Grotesk, and a tight 8px radius.
//
//   customer site            here
//   --background  oklch(.145 0 0)  ->  #0A0A0A
//   --card        oklch(.205 0 0)  ->  #171717
//   --accent      oklch(.222 0 0)  ->  #1F1F1F
//   --foreground  oklch(.985 0 0)  ->  #FAFAFA
//   --muted-fg    oklch(.708 0 0)  ->  #A1A1A1
//   --primary     #ef4444          ->  #EF4444 (dark) / #DC2626 (light)
//   --radius      0.45rem          ->  8px
const RADIUS = 8;

const FONT_STACK = '"Space Grotesk", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';

const buildTheme = (mode) => {
  const dark = mode === 'dark';
  const accentGlow = dark ? 'rgba(239,68,68,0.45)' : 'rgba(220,38,38,0.28)';

  return {
    palette: dark
      ? {
          mode: 'dark',
          primary: { main: '#EF4444', light: '#F87171', dark: '#DC2626', contrastText: '#FFFFFF' },
          background: { default: '#0A0A0A', paper: '#171717' },
          text: { primary: '#FAFAFA', secondary: '#A1A1A1', disabled: '#737373' },
          divider: 'rgba(255,255,255,0.11)',
        }
      : {
          mode: 'light',
          primary: { main: '#DC2626', light: '#EF4444', dark: '#B91C1C', contrastText: '#FFFFFF' },
          background: { default: '#FAFAFA', paper: '#FFFFFF' },
          text: { primary: '#0A0A0A', secondary: '#737373', disabled: '#A1A1A1' },
          divider: '#E5E5E5',
        },
    shape: {
      borderRadius: RADIUS,
    },
    typography: {
      fontFamily: FONT_STACK,
      // Headings get the tighter tracking / heavier weight the storefront uses
      // for its display type.
      h1: { fontWeight: 700, letterSpacing: '-0.03em' },
      h2: { fontWeight: 700, letterSpacing: '-0.025em' },
      h3: { fontWeight: 700, letterSpacing: '-0.02em' },
      h4: { fontWeight: 700, letterSpacing: '-0.02em' },
      h5: { fontWeight: 600, letterSpacing: '-0.015em' },
      h6: { fontWeight: 600, letterSpacing: '-0.01em' },
      button: { fontWeight: 600, letterSpacing: '0.01em' },
      overline: { fontWeight: 700, letterSpacing: '0.1em' },
    },
    components: {
      // Subtle press feedback on every clickable surface (buttons, icon
      // buttons, list items, tabs, card action areas all share ButtonBase) -
      // small, universal, doesn't touch layout or color.
      MuiButtonBase: {
        styleOverrides: {
          root: {
            transition: 'transform .12s ease',
            '&:active': {
              transform: 'scale(0.97)',
            },
          },
        },
      },
      MuiPaper: {
        styleOverrides: {
          root: {
            borderRadius: RADIUS,
            backgroundImage: 'none',
          },
        },
      },
      MuiButton: {
        styleOverrides: {
          root: {
            borderRadius: RADIUS,
            textTransform: 'none',
          },
          containedPrimary: {
            boxShadow: `0 10px 24px -12px ${accentGlow}`,
            '&:hover': {
              boxShadow: `0 12px 28px -10px ${accentGlow}`,
            },
          },
        },
      },
      MuiCard: {
        styleOverrides: {
          root: {
            borderRadius: RADIUS,
            backgroundImage: 'none',
          },
        },
      },
      MuiChip: {
        styleOverrides: {
          root: { borderRadius: RADIUS - 2, fontWeight: 600 },
        },
      },
      MuiTab: {
        styleOverrides: {
          root: { textTransform: 'none', fontWeight: 600, letterSpacing: '-0.01em' },
        },
      },
    },
  };
};

export default buildTheme;
export { FONT_STACK };
