import React, { useState, useEffect, useCallback, useMemo, useRef, lazy, Suspense } from 'react';
import {
  Box, Grid, CircularProgress, Alert, Paper,
  Dialog, DialogContent, DialogTitle, DialogActions, Button, Snackbar,
  Typography, List, ListItem, ListItemText,
} from '@mui/material';
import HomeOutlinedIcon from '@mui/icons-material/HomeOutlined';
import Inventory2OutlinedIcon from '@mui/icons-material/Inventory2Outlined';
import RequestQuoteOutlinedIcon from '@mui/icons-material/RequestQuoteOutlined';
import PointOfSaleOutlinedIcon from '@mui/icons-material/PointOfSaleOutlined';
import LocalActivityOutlinedIcon from '@mui/icons-material/LocalActivityOutlined';
import WorkOutlineOutlinedIcon from '@mui/icons-material/WorkOutlineOutlined';
import QrCode2OutlinedIcon from '@mui/icons-material/QrCode2Outlined';
import LoyaltyOutlinedIcon from '@mui/icons-material/LoyaltyOutlined';
import EventNoteOutlinedIcon from '@mui/icons-material/EventNoteOutlined';
import ContactPageOutlinedIcon from '@mui/icons-material/ContactPageOutlined';
import ListAltOutlinedIcon from '@mui/icons-material/ListAltOutlined';
import ChecklistOutlinedIcon from '@mui/icons-material/ChecklistOutlined';
import FactCheckOutlinedIcon from '@mui/icons-material/FactCheckOutlined';
import BugReportOutlinedIcon from '@mui/icons-material/BugReportOutlined';
import AppsOutlinedIcon from '@mui/icons-material/AppsOutlined';
import roleConfig from './roleConfig';
import { useUserData } from './UserContext';
import { CheckInProvider } from './CheckInContext';
import AuthComponent from './AuthComponent';
import { guidesConfig } from './guidesConfig';
import { onSessionExpired } from './api';
import { clearWidgetCache } from './widgetCache';
import { resetHomeData } from './homeData';
import { preloadWhenIdle } from './lazyWithPreload';
import Sidebar from './layout/Sidebar';
import TopBar from './layout/TopBar';

// Loaded on first open, like the apps in roleConfig.
const TaskManager = lazy(() => import('./TaskManager'));
const Approvals = lazy(() => import('./Approvals'));
const ListerApp = lazy(() => import('./lister/lister'));

// Home widgets that can wait a moment. The others load together in one
// batched getHomeData request (see homeData.js); the calendar has its own,
// slower lookup (8 Google Calendars), so it goes out a moment later rather
// than competing with that first request.
const DEFERRED_WIDGETS = new Set(['GoogleCalendar']);
const DEFERRED_WIDGET_DELAY_MS = 1200;

const WidgetPlaceholder = () => (
  <Paper sx={{ minHeight: 160, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
    <CircularProgress size={28} />
  </Paper>
);

const PageLoading = () => (
  <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}>
    <CircularProgress />
  </Box>
);

// Names that used to open as a modal "app" (card + dialog) rather than
// render inline on the dashboard - these now get their own sidebar entry
// and full-page view instead of a dialog. Keeping this list intact (rather
// than re-deriving it) preserves exactly which roleConfig entries are
// "apps" vs. always-visible widgets, including ones currently archived.
const CARD_COMPONENT_NAMES = new Set([
  'Lister', 'Checkout', 'Accounting', 'TaskManager', 'Register', 'EventManager',
  'Careers Manager', 'StoreSearch', 'QrCodeGenerator', 'LoyaltyDashboard',
  'ScheduleForm', 'CardSearch', 'testUser',
]);

const NAV_LABELS = {
  StoreSearch: 'Store Search',
  EventManager: 'Event Manager',
  QrCodeGenerator: 'QR Code Generator',
  LoyaltyDashboard: 'Loyalty Dashboard',
  ScheduleForm: 'Schedule',
  CardSearch: 'Card Search',
  TaskManager: 'Task Manager',
  testUser: 'Test User',
};

const NAV_ICONS = {
  home: HomeOutlinedIcon,
  StoreSearch: Inventory2OutlinedIcon,
  Accounting: RequestQuoteOutlinedIcon,
  Register: PointOfSaleOutlinedIcon,
  EventManager: LocalActivityOutlinedIcon,
  'Careers Manager': WorkOutlineOutlinedIcon,
  QrCodeGenerator: QrCode2OutlinedIcon,
  LoyaltyDashboard: LoyaltyOutlinedIcon,
  ScheduleForm: EventNoteOutlinedIcon,
  CardSearch: ContactPageOutlinedIcon,
  Lister: ListAltOutlinedIcon,
  TaskManager: ChecklistOutlinedIcon,
  Approvals: FactCheckOutlinedIcon,
  testUser: BugReportOutlinedIcon,
};

const navLabel = (name) => NAV_LABELS[name] || name;
const navIcon = (name) => NAV_ICONS[name] || AppsOutlinedIcon;

const Dashboard = () => {
  const { userData, setUserData } = useUserData();
  const [loading] = useState(false);
  const [error, setError] = useState(null);
  const [activeView, setActiveView] = useState('home');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [jobDescription, setJobDescription] = useState(null);
  const [showJobDescription, setShowJobDescription] = useState(false);
  const [openGuide, setOpenGuide] = useState(null);
  const [, setComponentMaxWidth] = useState('md');
  const [componentBusy, setComponentBusy] = useState(false);
  const [busyNotice, setBusyNotice] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [showDeferredWidgets, setShowDeferredWidgets] = useState(false);
  const [sessionExpired, setSessionExpired] = useState(false);
  const openComponentRef = useRef(null);

  // Any API call that comes back "invalid authentication" (e.g. the account
  // signed in somewhere else) raises this. Ask the user to sign in again
  // rather than leaving widgets silently failing behind a working-looking page.
  // Only for the CURRENT session: when a session ends, several requests fail
  // at different times, and the slow ones can land after the user has already
  // clicked "Sign in again" (or even logged back in). Those carry the old
  // login token, so they're ignored instead of reopening the dialog.
  const currentTokenRef = useRef(null);
  currentTokenRef.current = userData ? userData.googleToken : null;
  useEffect(() => onSessionExpired(({ googleToken } = {}) => {
    const current = currentTokenRef.current;
    if (!current) return; // signed out already
    if (googleToken && googleToken !== current) return; // from an earlier session
    setSessionExpired(true);
  }), []);

  // Every new sign-in starts clean.
  useEffect(() => {
    if (!userData) return;
    setSessionExpired(false);
    resetHomeData();
  }, [userData]);

  const signInAgain = useCallback(() => {
    clearWidgetCache();
    setSessionExpired(false);
    setActiveView('home');
    setUserData(null);
  }, [setUserData]);

  const memoizedRoleConfig = useMemo(() =>
    Object.fromEntries(
      Object.entries(roleConfig).map(([role, components]) => [
        role,
        components.map(({ component, ...rest }) => ({
          ...rest,
          component: typeof component === 'function' ? React.memo(component) : component
        }))
      ])
    ),
    []
  );

  const availableRoles = useMemo(() => Object.keys(memoizedRoleConfig), [memoizedRoleConfig]);

  useEffect(() => {
    if (userData && userData.role && !availableRoles.includes(userData.role)) {
      setError(`Invalid role: ${userData.role}. Please contact an administrator.`);
    } else {
      setError(null);
    }
  }, [userData, availableRoles]);

  useEffect(() => {
    setIsAuthenticated(!!userData);
    if (userData && userData.jobDescription) {
      try {
        const parsedJobDescription = JSON.parse(userData.jobDescription);
        setJobDescription(parsedJobDescription);
      } catch (error) {
        console.error('Error parsing job description:', error);
        setJobDescription(null);
      }
    } else {
      setJobDescription(null);
    }
  }, [userData]);

  useEffect(() => {
    if (!isAuthenticated) {
      setShowDeferredWidgets(false);
      return undefined;
    }
    const timer = setTimeout(() => setShowDeferredWidgets(true), DEFERRED_WIDGET_DELAY_MS);
    return () => clearTimeout(timer);
  }, [isAuthenticated]);

  // Always-visible dashboard widgets (everything NOT in CARD_COMPONENT_NAMES)
  // vs. "apps" that get their own sidebar entry and full page.
  const widgetItems = useMemo(() => {
    if (!userData?.role || !memoizedRoleConfig[userData.role]) return [];
    return memoizedRoleConfig[userData.role].filter(c => !CARD_COMPONENT_NAMES.has(c.name));
  }, [userData, memoizedRoleConfig]);

  const appItems = useMemo(() => {
    if (!userData?.role || !memoizedRoleConfig[userData.role]) return [];
    return memoizedRoleConfig[userData.role].filter(c => CARD_COMPONENT_NAMES.has(c.name));
  }, [userData, memoizedRoleConfig]);

  const sidebarSections = useMemo(() => {
    const sections = [
      { title: 'My Day', items: [{ key: 'home', label: 'Home', icon: navIcon('home') }] },
    ];
    if (appItems.length) {
      sections.push({
        title: 'Apps',
        items: appItems.map(({ name }) => ({ key: name, label: navLabel(name), icon: navIcon(name) })),
      });
    }
    return sections;
  }, [appItems]);

  // Once the home page has had its turn (deferred widgets started), quietly
  // download the code for this role's apps so opening one is instant. Only
  // the apps this role can see; the login page never pays for any of it.
  useEffect(() => {
    if (!showDeferredWidgets) return undefined;
    return preloadWhenIdle(appItems.map((item) => item.component));
  }, [showDeferredWidgets, appItems]);

  // If the active app disappears (role change, feature archived) fall back home.
  useEffect(() => {
    const specialViews = ['TaskManager', 'Approvals', 'Lister'];
    if (activeView !== 'home' && !specialViews.includes(activeView) && !appItems.some(a => a.name === activeView)) {
      setActiveView('home');
    }
  }, [appItems, activeView]);

  const goTo = useCallback((key) => {
    setActiveView(key);
    setComponentMaxWidth('md');
    setComponentBusy(false);
  }, []);

  // An app's own Close button always goes home.
  const finishNavigation = useCallback(() => goTo('home'), [goTo]);

  // If the currently-open app exposes a requestClose() (via ref), let IT
  // decide whether to navigate away immediately or show its own busy/
  // unsaved-changes confirmation first - keeps a single, consistent
  // confirmation UI regardless of where the user navigates to next. Apps
  // that don't expose this (TaskManager, Approvals, ListerApp) just switch
  // pages immediately, same as before.
  const requestNavigate = useCallback((key) => {
    if (key === activeView) {
      setMobileNavOpen(false);
      return;
    }
    if (activeView !== 'home' && componentBusy) {
      // The open app is mid-request (loading/saving) and refuses to close, as it
      // did in the dialog. Say so instead of ignoring the click, and don't queue
      // a target that nothing will ever consume.
      setBusyNotice(true);
    } else if (activeView !== 'home' && openComponentRef.current && typeof openComponentRef.current.requestClose === 'function') {
      // The destination travels with this one request: if the user cancels
      // the app's "unsaved changes" prompt it's simply dropped, rather than
      // waiting around to hijack a later Close.
      openComponentRef.current.requestClose(() => goTo(key));
    } else {
      setActiveView(key);
    }
    setMobileNavOpen(false);
  }, [activeView, componentBusy, goTo]);

  const renderJobDescription = (description) => {
    if (!description) return null;

    return (
      <>
        <Typography variant="h4" gutterBottom>{description.title}</Typography>
        {description.sections.map((section, sectionIndex) => (
          <div key={sectionIndex}>
            <Typography variant="h5" gutterBottom>{section.title}</Typography>
            {section.subsections.map((subsection, subsectionIndex) => (
              <div key={subsectionIndex}>
                {subsection.title && (
                  <Typography variant="h6" gutterBottom>{subsection.title}</Typography>
                )}
                <List>
                  {subsection.items.map((item, itemIndex) => (
                    <ListItem key={itemIndex}>
                      <ListItemText primary={item} />
                    </ListItem>
                  ))}
                </List>
              </div>
            ))}
          </div>
        ))}
      </>
    );
  };

  // Widgets render straight from the (memoized) role config and are keyed by
  // name. The previous version accumulated them into state one setTimeout at a
  // time, which double-ran under StrictMode and could mount a widget twice.
  // The staggered entrance is now pure CSS, so nothing can get appended twice.
  const homeContent = useMemo(() => (
    <Grid container spacing={3}>
      {widgetItems.map(({ component: Component, gridProps, name }, index) => {
        if (!Component) {
          console.error(`Component not found for ${name}`);
          return null;
        }
        return (
          <Grid
            item
            key={name}
            {...gridProps}
            sx={{
              animation: 'yuranka-widget-in .32s ease-out both',
              animationDelay: `${Math.min(index, 8) * 60}ms`,
              '@keyframes yuranka-widget-in': {
                from: { opacity: 0, transform: 'translateY(8px)' },
                to: { opacity: 1, transform: 'none' },
              },
              '@media (prefers-reduced-motion: reduce)': { animation: 'none' },
            }}
          >
            {DEFERRED_WIDGETS.has(name) && !showDeferredWidgets ? (
              <WidgetPlaceholder />
            ) : (
              <Suspense fallback={<WidgetPlaceholder />}>
                <Component />
              </Suspense>
            )}
          </Grid>
        );
      })}
    </Grid>
  ), [widgetItems, showDeferredWidgets]);

  const pageContent = useMemo(() => {
    if (activeView === 'home' || !userData || !userData.role || !memoizedRoleConfig[userData.role]) return null;

    if (activeView === 'TaskManager') {
      return <TaskManager onClose={finishNavigation} />;
    }

    if (activeView === 'Approvals') {
      return <Approvals onClose={finishNavigation} />;
    }

    if (activeView === 'Lister') {
      return <ListerApp onMaxWidthChange={setComponentMaxWidth} />;
    }

    const componentConfig = memoizedRoleConfig[userData.role].find(c => c.name === activeView);
    if (!componentConfig || !componentConfig.component) return null;
    const Component = componentConfig.component;
    // Only StoreSearch currently supports the requestClose() ref interface;
    // passing a ref to the other (non-forwardRef) components here would just
    // log a harmless-but-noisy React warning, so scope it to StoreSearch.
    const componentRef = activeView === 'StoreSearch' ? openComponentRef : null;
    return <Component ref={componentRef} onClose={finishNavigation} onMaxWidthChange={setComponentMaxWidth} onBusyChange={setComponentBusy} />;
  }, [activeView, userData, finishNavigation, memoizedRoleConfig]);

  const renderGuideContent = (guide) => {
    if (!guide) return null;

    return (
      <Box sx={{ padding: 2 }}>
        <Typography variant="h4" gutterBottom>
          {guide.title}
        </Typography>

        {guide.content && (
          <Typography variant="body1" paragraph>
            {guide.content}
          </Typography>
        )}

        {guide.sections?.map((section, sectionIndex) => (
          <Box key={sectionIndex} sx={{ mb: 3 }}>
            <Typography variant="h5" gutterBottom>
              {section.title}
            </Typography>

            {section.content && (
              <Typography variant="body1" paragraph>
                {section.content}
              </Typography>
            )}

            {section.subsections?.map((subsection, subsectionIndex) => (
              <Box key={subsectionIndex} sx={{ ml: 2, mb: 2 }}>
                {subsection.title && (
                  <Typography variant="h6" gutterBottom>
                    {subsection.title}
                  </Typography>
                )}

                <List>
                  {subsection.items?.map((item, itemIndex) => (
                    <ListItem key={itemIndex}>
                      <ListItemText
                        primary={item.title}
                        secondary={item.description}
                      />
                    </ListItem>
                  ))}
                </List>
              </Box>
            ))}
          </Box>
        ))}
      </Box>
    );
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress aria-label="Loading dashboard" />
      </Box>
    );
  }

  if (error) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <Alert severity="error">{error}</Alert>
      </Box>
    );
  }

  if (!isAuthenticated) {
    return <AuthComponent onAuthenticated={setIsAuthenticated} setUserData={setUserData} />;
  }

  const pageTitle = activeView === 'home' ? 'Home' : navLabel(activeView);
  const guideAvailable = activeView !== 'home' && !!guidesConfig[activeView];
  const firstName = (userData?.username || '').trim().split(/\s+/)[0] || userData?.username || '';
  const currentHour = new Date().getHours();
  const greeting = currentHour < 12 ? 'Good morning' : currentHour < 18 ? 'Good afternoon' : 'Good evening';
  const todayLabel = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });

  return (
    <CheckInProvider>
      <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'background.default' }}>
        <Sidebar
          sections={sidebarSections}
          activeKey={activeView}
          onSelect={requestNavigate}
          collapsed={sidebarCollapsed}
          onToggleCollapse={() => setSidebarCollapsed((c) => !c)}
          mobileOpen={mobileNavOpen}
          onCloseMobile={() => setMobileNavOpen(false)}
        />

        <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', minWidth: 0 }}>
          <TopBar
            title={pageTitle}
            pageIcon={navIcon(activeView)}
            username={userData?.username}
            role={userData?.role}
            onMobileMenuClick={() => setMobileNavOpen(true)}
            onShowJobDescription={jobDescription ? () => setShowJobDescription(true) : undefined}
            guideAvailable={guideAvailable}
            onShowGuide={() => setOpenGuide(activeView)}
          />

          <Box component="main" sx={{ flex: 1, overflowY: 'auto', p: { xs: 2, sm: 3, md: 4 } }}>
            {/* Home stays mounted (just hidden) while an app page is open, as it
                did when apps opened in a dialog on top of it - so the widgets
                keep their state (e.g. the month picked in Work History) and
                don't re-fetch every time you come back. */}
            <Box sx={{ display: activeView === 'home' ? 'block' : 'none' }}>
              <Box sx={{ mb: 3 }}>
                <Typography variant="h4">
                  {greeting}{firstName ? `, ${firstName}` : ''}
                </Typography>
                <Typography variant="body1" color="text.secondary">
                  {todayLabel} · {userData?.role}
                </Typography>
              </Box>
              {homeContent}
            </Box>
            {activeView !== 'home' && (
              <Box sx={{ maxWidth: 1200, mx: 'auto' }}>
                <Suspense fallback={<PageLoading />}>
                  {pageContent}
                </Suspense>
              </Box>
            )}
          </Box>
        </Box>

        <Dialog
          open={openGuide !== null}
          onClose={() => setOpenGuide(null)}
          maxWidth="md"
          fullWidth
        >
          <DialogTitle>
            {openGuide && guidesConfig[openGuide]?.title}
          </DialogTitle>
          <DialogContent>
            {openGuide && guidesConfig[openGuide] ? (
              renderGuideContent(guidesConfig[openGuide])
            ) : (
              <Typography>No guide available for this module.</Typography>
            )}
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setOpenGuide(null)}>Close</Button>
          </DialogActions>
        </Dialog>

        <Dialog open={sessionExpired} maxWidth="xs" fullWidth>
          <DialogTitle>You've been signed out</DialogTitle>
          <DialogContent>
            <Typography>
              Your session ended, usually because this account signed in on another
              device or tab. Sign in again to keep working - nothing on this page
              will refresh until you do.
            </Typography>
          </DialogContent>
          <DialogActions>
            <Button variant="contained" onClick={signInAgain}>Sign in again</Button>
          </DialogActions>
        </Dialog>

        <Snackbar
          open={busyNotice}
          autoHideDuration={3500}
          onClose={() => setBusyNotice(false)}
          message="Still loading or saving - you can switch pages in a moment."
          anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        />

        <Dialog open={showJobDescription} onClose={() => setShowJobDescription(false)} maxWidth="md" fullWidth>
          <DialogTitle>Job Description</DialogTitle>
          <DialogContent>
            {jobDescription ? renderJobDescription(jobDescription) : <Typography>No job description available.</Typography>}
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setShowJobDescription(false)}>Close</Button>
          </DialogActions>
        </Dialog>
      </Box>
    </CheckInProvider>
  );
};

export default React.memo(Dashboard);
