import apiCall from './api';

// Batches the home widgets' first load into one getHomeData request (one
// Apps Script run reading each sheet once) instead of one request per widget.
//
// Widgets ask for their own section with requestHomeSection(); every request
// made in the same tick - i.e. by widgets mounting together - goes out as a
// single call. A widget whose section can't come from the batch (backend not
// updated yet, section failed, joined too late) gets a rejected promise and
// falls back to its own single action, so nothing depends on this working.

let openBatch = null;
// Set once a getHomeData call fails outright (e.g. the deployed backend or
// proxy doesn't know the action yet), so later page loads in this tab don't
// keep paying for a request that can't succeed.
let homeDataUnavailable = false;

const sendBatch = (batch) => {
  openBatch = null;
  const now = new Date();
  return apiCall('dashboard_script', 'getHomeData', {
    username: batch.userData.username,
    googleToken: batch.userData.googleToken,
    sections: Array.from(batch.sections),
    // The browser's current month, so it matches what the History widget shows.
    year: now.getFullYear(),
    month: now.getMonth() + 1,
  }).then((result) => {
    if (!result || typeof result !== 'object' || result.error) {
      throw new Error((result && result.error) || 'getHomeData unavailable');
    }
    return result;
  }).catch((error) => {
    homeDataUnavailable = true;
    throw error;
  });
};

// A new sign-in starts fresh: a failure in the previous session (often the
// session itself ending) shouldn't keep this one off the batched request.
export const resetHomeData = () => {
  homeDataUnavailable = false;
  openBatch = null;
};

export const requestHomeSection = (section, userData) => {
  if (homeDataUnavailable) return Promise.reject(new Error('getHomeData unavailable'));

  if (!openBatch) {
    const batch = { sections: new Set(), userData };
    batch.promise = new Promise((resolve) => setTimeout(resolve, 0)).then(() => sendBatch(batch));
    openBatch = batch;
  }
  openBatch.sections.add(section);

  return openBatch.promise.then((result) => {
    const entry = result[section];
    if (!entry || entry.error !== undefined || !('data' in entry)) {
      throw new Error((entry && entry.error) || `Section ${section} missing`);
    }
    return entry.data;
  });
};

// First load: take the section from the batched home request, falling back to
// the widget's own single call if that doesn't work out. Later refreshes go
// straight to the single call.
export const loadHomeSection = (section, userData, single, { firstLoad } = {}) => {
  if (!firstLoad) return single();
  return requestHomeSection(section, userData).catch(() => single());
};
