import React, { useState, useEffect, useCallback } from "react";
import {
  Paper,
  Typography,
  Box,
  Button,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  CircularProgress,
  Alert,
  List,
  ListItem,
  ListItemText,
} from "@mui/material";
import apiCall from "./api";
import { useUserData } from "./UserContext";
import { useCachedResource } from "./widgetCache";
import { loadHomeSection } from "./homeData";
import { formatTime, formatBreakTime, formatHours, formatDateWithDayOfWeek } from "./timeFormat";

const currentYearDefault = new Date().getFullYear();
const currentMonthDefault = new Date().getMonth() + 1; // Months are 1-indexed for the API

const WorkerMonthlyWorkHistory = () => {
  const { userData } = useUserData();
  const [worker, setWorker] = useState("");
  const [year, setYear] = useState(currentYearDefault);
  const [month, setMonth] = useState(currentMonthDefault);
  const [results, setResults] = useState([]);
  const [fetchingResults, setFetchingResults] = useState(false);
  const [resultsError, setError] = useState(null);

  // Fetch all workers on load (cached, so the dropdown is usable immediately
  // on later visits while the list refreshes in the background)
  const loadUsernames = useCallback(async ({ firstLoad } = {}) => {
    const response = await loadHomeSection("workerUsernames", userData, () => apiCall(
      "dashboard_script",
      "getRegularUserUsernames",
      {
        username: userData.username,
        googleToken: userData.googleToken,
      }
    ), { firstLoad });
    if (Array.isArray(response)) return response;
    throw new Error("Could not load workers");
  }, [userData]);
  const { data: usernameData, loading: refreshingUsers, error: usersError } =
    useCachedResource("workerUsernames", loadUsernames);
  const usernames = usernameData || [];
  const fetchingUsers = refreshingUsers && usernameData === undefined;
  const error = resultsError
    || (usersError && usernameData === undefined ? "Failed to load workers: " + usersError.message : null);

  // Filters: if any filter changes, clear results
  useEffect(() => {
    setResults([]);
    setError(null);
  }, [worker, year, month]);

  // Year selector options
  const years = [
    currentYearDefault - 1,
    currentYearDefault,
    currentYearDefault + 1,
  ];

  // Month selector options
  const months = Array.from({ length: 12 }, (_, i) => i + 1);

  const handleSearch = async () => {
    setError(null);
    if (!year || !month || !worker) {
      let missing = [];
      if (!year) missing.push("Year");
      if (!month) missing.push("Month");
      if (!worker) missing.push("Worker");
      alert(
        `Please select the following before searching: ${missing.join(", ")}`
      );
      return;
    }
    setFetchingResults(true);
    try {
      const response = await apiCall(
        "dashboard_script",
        "getUserWorkForMonth",
        {
          username: userData.username,
          year,
          month: String(month).padStart(2, "0"),
          googleToken: userData.googleToken,
          workerUsername: worker,
        }
      );
      if (response && response.success && Array.isArray(response.records)) {
        console.log("Fetched records:", response.records);
        setResults(response.records);
      } else {
        setResults([]);
        setError("No data found or unexpected response.");
      }
    } catch (err) {
      setError("Error fetching records: " + err.message);
      setResults([]);
    } finally {
      setFetchingResults(false);
    }
  };

  return (
    <Paper elevation={4} sx={{ p: 3 }}>
      <Typography variant="h5" gutterBottom>
        Worker Monthly Work History
      </Typography>
      <Box
        sx={{
          display: "flex",
          gap: 2,
          alignItems: "center",
          mb: 2,
          flexWrap: "wrap",
        }}
      >
        {/* Year Filter */}
        <FormControl sx={{ minWidth: 100 }}>
          <InputLabel>Year</InputLabel>
          <Select
            label="Year"
            value={year}
            onChange={(e) => setYear(e.target.value)}
          >
            {years.map((y) => (
              <MenuItem value={y} key={y}>
                {y}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        {/* Month Filter */}
        <FormControl sx={{ minWidth: 100 }}>
          <InputLabel>Month</InputLabel>
          <Select
            label="Month"
            value={month}
            onChange={(e) => setMonth(e.target.value)}
          >
            {months.map((m) => (
              <MenuItem value={m} key={m}>
                {new Date(0, m - 1).toLocaleString("default", {
                  month: "long",
                })}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        {/* Worker Filter */}
        <FormControl sx={{ minWidth: 180 }}>
          <InputLabel>Worker</InputLabel>
          <Select
            label="Worker"
            value={worker}
            onChange={(e) => setWorker(e.target.value)}
            disabled={fetchingUsers}
          >
            {usernames.map((u) => (
              <MenuItem value={u} key={u}>
                {u}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        {/* Search Button */}
        <Button
          variant="contained"
          onClick={handleSearch}
          disabled={fetchingUsers || fetchingResults}
          sx={{ minWidth: 100, mt: { xs: 2, sm: 0 } }}
        >
          {fetchingResults ? <CircularProgress size={20} /> : "Search"}
        </Button>
      </Box>
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {/* Results */}
      {results.length > 0 && (
        <>
          <Typography variant="h6" gutterBottom>
            {`Results for ${worker} - ${new Date(0, month - 1).toLocaleString(
              "default",
              { month: "long" }
            )} - ${year}`}
          </Typography>
          <Box
            sx={{
              maxHeight: 550,
              overflowY: "auto",
              overflowX: "hidden",
              border: 1,
              borderColor: "divider",
              borderRadius: 1,
            }}
          >
            <List>
              {results.map((rec, idx) => (
                <ListItem key={idx} divider alignItems="flex-start">
                  <ListItemText
                    primary={formatDateWithDayOfWeek(rec.date)}
                    secondary={
                      <Box
                        component="span"
                        sx={{
                          display: "flex",
                          flexDirection: "column",
                          gap: 0.5,
                          mt: 0.5,
                        }}
                      >
                        <Typography component="span" variant="body2">
                          Hours: {formatHours(rec.hoursWorked)}
                          <span style={{ marginLeft: 12 }}>
                            Breaks: {rec.numberOfBreaks || 0}
                          </span>
                          <span style={{ marginLeft: 12 }}>
                            Break Time: {formatBreakTime(rec.totalBreakMinutes)}
                          </span>
                        </Typography>
                        <Typography component="span" variant="body2" color="text.secondary">
                          Check In: {formatTime(rec.checkInTime) || "—"}
                          <span style={{ marginLeft: 12 }}>
                            Check Out:{" "}
                            {rec.checkOutTime
                              ? formatTime(rec.checkOutTime)
                              : "Not Checked Out"}
                          </span>
                        </Typography>
                        <Typography
                          component="span"
                          variant="body2"
                          color="text.secondary"
                        >
                          Amount to be Paid:{" "}
                          {rec.amountPaid === "" || rec.amountPaid == null
                            ? "—"
                            : rec.amountPaid}€
                          <span style={{ marginLeft: 12 }}>
                            Salary:{" "}
                            {rec.salary === "" || rec.salary == null
                              ? "—"
                              : rec.salary}€
                          </span>
                        </Typography>
                        {(rec.breaks || []).length > 0 && (
                          <Box
                            component="span"
                            sx={{ display: "flex", flexWrap: "wrap", gap: 1 }}
                          >
                            {(rec.breaks || []).map((b, i) => (
                              <Typography
                                key={i}
                                component="span"
                                variant="body2"
                                color="text.secondary"
                              >
                                {formatTime(b.start)} →{" "}
                                {b.ongoing ? "Ongoing" : formatTime(b.end)} (
                                {formatBreakTime(b.durationMinutes)})
                              </Typography>
                            ))}
                          </Box>
                        )}
                        <Typography
                          component="span"
                          variant="body2"
                          color="text.secondary"
                        >
                          {rec.workDone || "No work details"}
                        </Typography>
                      </Box>
                    }
                  />
                </ListItem>
              ))}
            </List>
          </Box>
        </>
      )}

      {/* No results message */}
      {!fetchingResults && results.length === 0 && (
        <Box sx={{ mt: 2, color: "gray" }}>
          <Typography>
            No records to display. Please use the filters above and Search.
          </Typography>
        </Box>
      )}
    </Paper>
  );
};

export default WorkerMonthlyWorkHistory;
