import React from 'react';
import { AppBar, Toolbar, Typography, IconButton, Button, Box, Chip, Tooltip, useMediaQuery, useTheme } from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import DescriptionOutlinedIcon from '@mui/icons-material/DescriptionOutlined';
import LightModeOutlinedIcon from '@mui/icons-material/LightModeOutlined';
import DarkModeOutlinedIcon from '@mui/icons-material/DarkModeOutlined';
import { useThemeMode } from '../ThemeModeContext';

const TopBar = ({
  title, pageIcon: PageIcon, username, role,
  onMobileMenuClick, onShowJobDescription,
  guideAvailable, onShowGuide,
}) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { mode, toggleMode } = useThemeMode();

  return (
    <AppBar
      position="sticky"
      color="default"
      elevation={0}
      sx={{ borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper', borderRadius: 0 }}
    >
      <Toolbar sx={{ gap: 1 }}>
        {isMobile && (
          <IconButton edge="start" onClick={onMobileMenuClick} aria-label="Open menu" sx={{ mr: 0.5 }}>
            <MenuIcon />
          </IconButton>
        )}
        {PageIcon && (
          <Box sx={{
            width: 34, height: 34, borderRadius: '10px', flexShrink: 0,
            display: { xs: 'none', sm: 'flex' }, alignItems: 'center', justifyContent: 'center',
            bgcolor: 'action.selected', color: 'primary.main',
          }}>
            <PageIcon fontSize="small" />
          </Box>
        )}
        <Typography variant="h6" noWrap sx={{ flexShrink: 0 }}>
          {title}
        </Typography>
        {guideAvailable && (
          <Tooltip title="View guide">
            <IconButton size="small" onClick={onShowGuide} aria-label="View guide">
              <HelpOutlineIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        )}
        <Box sx={{ flexGrow: 1 }} />
        {!isMobile && username && (
          <Typography variant="body2" color="text.secondary" sx={{ mr: 0.5 }}>
            {username}
          </Typography>
        )}
        {role && (
          <Chip
            label={role}
            size="small"
            color="primary"
            variant="outlined"
            sx={{ fontWeight: 700, display: { xs: 'none', sm: 'inline-flex' } }}
          />
        )}
        {/* Only when there's a job description to show (login no longer
            loads one, so normally this is hidden). */}
        {onShowJobDescription && (
          <>
            <Button size="small" onClick={onShowJobDescription} sx={{ display: { xs: 'none', sm: 'inline-flex' } }}>
              Job Description
            </Button>
            {/* On phones the text button doesn't fit - keep the feature reachable as an icon. */}
            <Tooltip title="Job Description">
              <IconButton
                onClick={onShowJobDescription}
                aria-label="Job Description"
                sx={{ display: { xs: 'inline-flex', sm: 'none' } }}
              >
                <DescriptionOutlinedIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          </>
        )}
        <Tooltip title={mode === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}>
          <IconButton onClick={toggleMode} aria-label="Toggle light and dark mode">
            {mode === 'dark' ? <LightModeOutlinedIcon fontSize="small" /> : <DarkModeOutlinedIcon fontSize="small" />}
          </IconButton>
        </Tooltip>
      </Toolbar>
    </AppBar>
  );
};

export default TopBar;
