import React, { useState, useCallback } from 'react';
import {
  Typography, CircularProgress, Alert,
  Card, CardContent, List, ListItem, ListItemText,
  Button, Collapse, Box, Stack,
  TextField
} from '@mui/material';
import apiCall from './api';
import { useUserData } from './UserContext'; // Import the useUserData hook
import { useCachedResource } from './widgetCache';
import { loadHomeSection } from './homeData';

const PasswordDisplay = () => {
  const { userData } = useUserData(); // Use the userData context
  const [visiblePasswords, setVisiblePasswords] = useState({});
  const [copySuccess, setCopySuccess] = useState({});
  const [copyError, setError] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  const loadPasswords = useCallback(async ({ firstLoad } = {}) => {
    const response = await loadHomeSection('passwords', userData, () => apiCall('dashboard_script', 'getUserPassforrole', {
      role: userData.role,
      googleToken: userData.googleToken,
      username: userData.username
    }), { firstLoad });
    if (response && Array.isArray(response)) return response;
    throw new Error('Failed to fetch passwords');
  }, [userData]);

  // cache: false - these are credentials, so they're never written to browser
  // storage; this widget always loads fresh.
  const { data, loading, error: fetchError } = useCachedResource('passwords', loadPasswords, { cache: false });
  const passwords = data || [];
  const error = (fetchError && 'Failed to load passwords. Please try again.') || copyError;


  const handleTogglePasswordVisibility = useCallback((index) => {
    setVisiblePasswords(prev => ({
      ...prev,
      [index]: !prev[index]
    }));
  }, []);

  const handleCopyPassword = useCallback((password, index) => {
    navigator.clipboard.writeText(password).then(() => {
      setCopySuccess(prev => ({
        ...prev,
        [index]: true
      }));
      setTimeout(() => {
        setCopySuccess(prev => ({
          ...prev,
          [index]: false
        }));
      }, 3000);
    }, (err) => {
      console.error('Failed to copy password:', err);
      setError('Failed to copy password. Please try again.');
      setTimeout(() => setError(null), 3000);
    });
  }, []);

  const filteredPasswords = passwords.filter((entry) => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return true;

    const website = (entry.website || '').toString().toLowerCase();
    const username = (entry.username || '').toString().toLowerCase();
    return website.includes(q) || username.includes(q);
  });

  if (loading) {
    return (
      <Card>
        <CardContent style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 100 }}>
          <CircularProgress />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card sx={{ height: '400px', display: 'flex', flexDirection: 'column' }}>
      <CardContent sx={{ flexGrow: 0 }}>
        <Typography variant="h6" gutterBottom>
          Passwords for {userData.role}
        </Typography>

        <TextField
          fullWidth
          size="small"
          label="Search"
          placeholder="Search by website or username..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          sx={{ mt: 3 , mb: 2 }}
        />

        {error && (
          <Alert severity="error" sx={{ marginBottom: 2 }}>
            {error}
          </Alert>
        )}
      </CardContent>
      <Box sx={{ flexGrow: 1, overflow: 'auto', px: 2 }}>
        <List sx={{ width: '100%' }}>
          {filteredPasswords.map((entry, index) => (
            <ListItem 
              key={index} 
              divider 
              sx={{ 
                flexDirection: 'column', 
                alignItems: 'flex-start',
                py: 1, pb: 2
              }}
            >
              <ListItemText 
                primary={entry.website}
                secondary={
                  <>
                    <Typography component="span" variant="body2" color="textPrimary">
                      Username: {entry.username}
                    </Typography>
                    <br />
                    <Typography component="span" variant="body2" color="textPrimary">
                      Password: {visiblePasswords[index] ? entry.password : '••••••••'}
                    </Typography>
                  </>
                }
                sx={{ mb: 1 }}
              />
              <Stack direction="row" spacing={1}>
                <Button 
                  size="small" 
                  variant="outlined"
                  onClick={() => handleTogglePasswordVisibility(index)}
                >
                  {visiblePasswords[index] ? 'Hide' : 'Show'}
                </Button>
                <Button 
                  size="small" 
                  variant="outlined"
                  onClick={() => handleCopyPassword(entry.password, index)}
                >
                  Copy
                </Button>
              </Stack>
              <Collapse in={copySuccess[index]} timeout="auto" unmountOnExit sx={{ width: '100%', mt: 1 }}>
                <Alert severity="success">Password copied!</Alert>
              </Collapse>
            </ListItem>
          ))}
        </List>
      </Box>
    </Card>
  );
};

export default PasswordDisplay;