import SCRIPT_MAP from './scriptMap';

const HEROKU_BASE = 'https://isa-scavenger-761151e3e681.herokuapp.com';

// Everything dev-only below reads from .env.development.local, which
// `npm start` loads and `npm run build` never does, so none of it can reach
// the deployed site. The NODE_ENV checks are a second guard in case one of
// these is ever set in a file that builds do read (.env, .env.local).
const isDev = process.env.NODE_ENV !== 'production';

// The proxy only lets allowed origins through CORS; the live site is one of
// them. localhost isn't, so in dev the bypass key is added to the URL.
const bypassKey = isDev ? process.env.REACT_APP_CORS_BYPASS_KEY : undefined;
const proxyUrl = (base, path) =>
  bypassKey ? `${base}${path}?bypass_key=${bypassKey}` : `${base}${path}`;

// Comma-separated short names of backends to route to the local dev server,
// e.g. REACT_APP_LOCAL_SCRIPTS=dashboard,cardmanager
const localScriptNames = new Set(
  (process.env.REACT_APP_LOCAL_SCRIPTS || '')
    .split(',')
    .map(s => s.trim().toLowerCase())
    .filter(Boolean)
);

// Resolves the proxy base URL per call: only scripts listed in
// REACT_APP_LOCAL_SCRIPTS (and mapped in scriptMap.js) point at the local
// backend; everything else keeps hitting the production Heroku proxy.
// The 'login' action always goes to production: it writes the auth token to
// the shared admin sheet, and a locally-generated token is never persisted
// (dev writes are no-ops), so production backends would reject it.
const proxyBase = (scriptId, action) => {
  if (action === 'login') return HEROKU_BASE;
  const name = SCRIPT_MAP[scriptId];
  return (isDev && process.env.REACT_APP_API_PROXY_URL && name && localScriptNames.has(name))
    ? process.env.REACT_APP_API_PROXY_URL
    : HEROKU_BASE;
};

// Timeouts. Heroku's router drops any request after 30s and the proxy gives
// Apps Script 25s, so waiting longer than this never gets an answer - it just
// leaves a spinner up. A token is a tiny signing request on the proxy itself.
const REQUEST_TIMEOUT_MS = 35000;
const TOKEN_TIMEOUT_MS = 15000;

// Retries: only for failures that can clear up on their own (network blips,
// timeouts, 5xx from the proxy). 2 retries, 1s then 2s apart.
const MAX_ATTEMPTS = 3;
const RETRY_BASE_DELAY_MS = 1000;

// Proxy tokens are valid for 300s and are scoped to script + action only (not
// to the user), so one can be reused for repeat calls instead of asking for a
// new one every time. Kept a minute short of expiry to be safe.
const TOKEN_CACHE_MS = 240000;

// What each backend sends back (as HTTP 200 JSON) when the user's login token
// no longer matches - e.g. they signed in again somewhere else.
const SESSION_EXPIRED_ERRORS = new Set([
  'Invalid authentication',            // dashboard
  'Authentication required',           // dashboard
  'Invalid authentication credentials', // loyalty
  'Invalid webhook request',           // tournament, stocker (website calls)
]);

class ApiError extends Error {
  constructor(message, { status, retryable = false } = {}) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.retryable = retryable;
  }
}

export class SessionExpiredError extends Error {
  constructor() {
    super('Your session has ended. Please sign in again.');
    this.name = 'SessionExpiredError';
  }
}

// Lets the app react (e.g. show "sign in again") without every component
// having to check for it. Listeners get { googleToken } - the login token the
// rejected request used - so a late failure from an earlier session can be
// told apart from the current one.
const sessionExpiredListeners = new Set();
export const onSessionExpired = (listener) => {
  sessionExpiredListeners.add(listener);
  return () => sessionExpiredListeners.delete(listener);
};

const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const fetchWithTimeout = async (url, options, timeout) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeout);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } catch (error) {
    // Aborted (timed out) or never reached the server - both worth a retry.
    throw new ApiError(
      error.name === 'AbortError' ? 'The server took too long to respond' : 'Could not reach the server',
      { retryable: true }
    );
  } finally {
    clearTimeout(timeoutId);
  }
};

const ensureOk = async (response) => {
  if (response.ok) return;
  const detail = await response.text().catch(() => '');
  if (isDev) console.error(`API call failed (${response.status}):`, detail);
  throw new ApiError(`Server error: ${response.status} ${response.statusText}`, {
    status: response.status,
    // 429: the proxy's per-minute rate limit - waiting a moment clears it.
    retryable: response.status >= 500 || response.status === 429,
  });
};

const withRetries = async (fn, canRetry) => {
  for (let attempt = 1; ; attempt++) {
    try {
      return await fn();
    } catch (error) {
      if (!canRetry || !error.retryable || attempt >= MAX_ATTEMPTS) throw error;
      const wait = RETRY_BASE_DELAY_MS * 2 ** (attempt - 1);
      if (isDev) console.log(`Attempt ${attempt} failed (${error.message}). Retrying in ${wait}ms...`);
      await delay(wait);
    }
  }
};

// cacheKey -> { token, expiresAt } once fetched, or { pending } while in flight,
// so the home page's widgets asking at the same time share one request.
const tokenCache = new Map();

const getProxyToken = (scriptId, action) => {
  const base = proxyBase(scriptId, action);
  const cacheKey = `${base}|${scriptId}|${action}`;
  const cached = tokenCache.get(cacheKey);
  if (cached?.pending) return cached.pending;
  if (cached && cached.expiresAt > Date.now()) return Promise.resolve(cached.token);

  const pending = withRetries(async () => {
    const response = await fetchWithTimeout(proxyUrl(base, '/get_token'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ script_id: scriptId, action }),
    }, TOKEN_TIMEOUT_MS);
    await ensureOk(response);
    const data = await response.json();
    if (!data.token) throw new ApiError('Failed to get token: ' + JSON.stringify(data));
    return data.token;
  }, true).then(
    (token) => {
      tokenCache.set(cacheKey, { token, expiresAt: Date.now() + TOKEN_CACHE_MS });
      return token;
    },
    (error) => {
      tokenCache.delete(cacheKey);
      throw error;
    }
  );
  tokenCache.set(cacheKey, { pending });
  return pending;
};

const forgetProxyToken = (scriptId, action) => {
  tokenCache.delete(`${proxyBase(scriptId, action)}|${scriptId}|${action}`);
};

// The proxy no longer needs the /get_token step: it checks the script/action
// allow-list itself, so each call is a single request. Proxies that haven't
// been updated yet (or the local test proxy) still want a token; the first
// "Missing token" answer from one marks it here and calls to it go back to
// fetching a token first - so the frontend works whichever deploys first.
const proxiesNeedingToken = new Set();
const proxyNeedsToken = (scriptId, action) => proxiesNeedingToken.has(proxyBase(scriptId, action));
const rememberProxyNeedsToken = (scriptId, action) => proxiesNeedingToken.add(proxyBase(scriptId, action));

const apiCall = async (scriptId, action, additionalData = {}) => {
  if (isDev) {
    // Payloads carry the login token and sometimes a password - never print them.
    const loggable = { ...additionalData };
    if (loggable.password) loggable.password = '***';
    if (loggable.googleToken) loggable.googleToken = '***';
    console.log(`API Call: ${scriptId} - ${action}`, loggable);
  }
  // Actions that must never run twice (creating an event, processing an order)
  // fail once rather than retry and risk a duplicate.
  const noRetry =
    (scriptId === 'admin_tournament_script' && action === 'createEvent') ||
    (scriptId === 'cardmanager_script' && action === 'processOrder');

  const send = async () => {
    const useToken = proxyNeedsToken(scriptId, action);
    const token = useToken ? await getProxyToken(scriptId, action) : undefined;
    return {
      useToken,
      response: await fetchWithTimeout(proxyUrl(proxyBase(scriptId, action), '/proxy'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, action, script_id: scriptId, ...additionalData }),
      }, REQUEST_TIMEOUT_MS),
    };
  };

  const makeRequest = async () => {
    let { useToken, response } = await send();
    // An older proxy that still requires a token answers 400 "Missing token"
    // before forwarding anything - remember that and redo it the old way.
    if (!useToken && response.status === 400) {
      const detail = await response.clone().text().catch(() => '');
      if (detail.includes('Missing token')) {
        rememberProxyNeedsToken(scriptId, action);
        ({ useToken, response } = await send());
      }
    }
    // The proxy rejects an expired token with 403 before forwarding anything,
    // so trying once more with a fresh token is safe even for noRetry actions.
    if (useToken && response.status === 403) {
      forgetProxyToken(scriptId, action);
      ({ response } = await send());
    }
    await ensureOk(response);
    const data = await response.json();
    if (action !== 'login' && data && SESSION_EXPIRED_ERRORS.has(data.error)) {
      sessionExpiredListeners.forEach((listener) => listener({ googleToken: additionalData.googleToken }));
      throw new SessionExpiredError();
    }
    return data;
  };

  return withRetries(makeRequest, !noRetry);
};

export default apiCall;